BEGIN TRANSACTION;
CREATE TABLE "actividades" ("id_actividad" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fecha" date NOT NULL, "solicitud" text NOT NULL, "accion" varchar(300) NOT NULL, "responsable" varchar(200) NOT NULL, "item_evaluacion" varchar(200) NOT NULL, "estado" varchar(30) NOT NULL, "contacto" varchar(200) NULL, "telefono" varchar(30) NULL, "ingreso_tubo" bool NOT NULL, "codigo_evidencia" varchar(50) NULL UNIQUE, "fecha_registro" datetime NOT NULL, "id_funcionario" integer NOT NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "codigo" varchar(30) NULL UNIQUE, "area_apoyo_tubo" varchar(200) NULL, "correo" varchar(254) NULL, "direccion" varchar(250) NULL, "es_gestion_social" bool NOT NULL, "fecha_entrega_beneficio" date NULL, "fecha_entrega_informe" date NULL, "fecha_limite_tubo" date NULL, "fecha_programada_visita" date NULL, "fecha_visita" date NULL, "id_compromiso" integer NULL REFERENCES "compromisos_tubo" ("id_compromiso") DEFERRABLE INITIALLY DEFERRED, "id_delegacion" integer NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "id_subatencion" integer NULL REFERENCES "sub_atenciones" ("id_subatencion") DEFERRABLE INITIALLY DEFERRED, "id_tipo" integer NULL REFERENCES "tipos_atencion" ("id_tipo") DEFERRABLE INITIALLY DEFERRED, "observaciones_sociales" text NULL, "primera_gestion" varchar(200) NULL, "requiere_visita" bool NOT NULL, "rut_solicitante" varchar(20) NULL, "segunda_gestion" varchar(200) NULL, "solicitante" varchar(200) NULL, "tercera_gestion" varchar(200) NULL, "id_atencion" integer NULL REFERENCES "atenciones_ciudadanas" ("id_atencion") DEFERRABLE INITIALLY DEFERRED, "id_gestion_social" integer NULL REFERENCES "gestiones_sociales" ("id_gestion_social") DEFERRABLE INITIALLY DEFERRED, "territorio" varchar(200) NULL, "usuario_creador_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "id_vecino" integer NULL REFERENCES "vecinos" ("id_vecino") DEFERRABLE INITIALLY DEFERRED, "asignacion_meta_id" integer NULL REFERENCES "metas_funcionario" ("id_meta") DEFERRABLE INITIALLY DEFERRED, "avance" integer NOT NULL, "hito_id" integer NULL REFERENCES "hitos_territoriales" ("id_hito") DEFERRABLE INITIALLY DEFERRED, "origen" varchar(50) NOT NULL, "responsable_funcionario_id" integer NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "resultado" varchar(255) NOT NULL, "id_gestion_padre" integer NULL REFERENCES "actividades" ("id_actividad") DEFERRABLE INITIALLY DEFERRED, "territorio_rel_id" integer NULL REFERENCES "territorios" ("id_territorio") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "atenciones_ciudadanas" ("id_atencion" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "folio" varchar(30) NOT NULL UNIQUE, "solicitante" varchar(200) NOT NULL, "rut_solicitante" varchar(20) NULL, "telefono" varchar(30) NULL, "correo" varchar(254) NULL, "direccion" varchar(250) NULL, "descripcion" text NOT NULL, "fecha_registro" datetime NOT NULL, "estado" varchar(30) NOT NULL, "id_delegacion" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "id_usuario" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "id_subatencion" integer NOT NULL REFERENCES "sub_atenciones" ("id_subatencion") DEFERRABLE INITIALLY DEFERRED, "id_tipo" integer NOT NULL REFERENCES "tipos_atencion" ("id_tipo") DEFERRABLE INITIALLY DEFERRED, "id_vecino" integer NULL REFERENCES "vecinos" ("id_vecino") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cargos_funcionarios" ("id_cargo" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codigo" varchar(20) NULL UNIQUE, "nombre" varchar(150) NOT NULL UNIQUE, "descripcion" text NOT NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL);
CREATE TABLE "cargos_tipos_gestion" ("id_cargo_tipo" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "cargo" varchar(150) NOT NULL, "fecha_creacion" datetime NOT NULL, "id_tipo" integer NOT NULL REFERENCES "tipos_atencion" ("id_tipo") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "compromisos_tubo" ("id_compromiso" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fecha_solicitud" date NOT NULL, "actividad" text NOT NULL, "tipo" varchar(10) NOT NULL, "solicitante" varchar(200) NOT NULL, "territorio" varchar(200) NULL, "responsable" varchar(200) NOT NULL, "fecha_compromiso" date NULL, "area_apoyo" varchar(200) NULL, "observaciones" text NULL, "estado" varchar(20) NOT NULL, "unidad" integer NOT NULL, "fecha_registro" datetime NOT NULL, "id_delegacion" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "id_responsable" integer NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "codigo" varchar(30) NULL UNIQUE, "id_actividad" integer NULL REFERENCES "actividades" ("id_actividad") DEFERRABLE INITIALLY DEFERRED, "usuario_creador_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "delegaciones" ("id_delegacion" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(200) NOT NULL UNIQUE, "ambito" varchar(150) NOT NULL, "responsable" varchar(200) NOT NULL, "foco_estrategico" text NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL, "comuna" varchar(100) NOT NULL, "direccion" varchar(250) NOT NULL, "delegado_id" integer NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "codigo" varchar(20) NULL UNIQUE);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "evidencias" ("id_evidencia" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codigo" varchar(50) NOT NULL UNIQUE, "archivo_ruta" varchar(255) NULL, "imagen_verificada" bool NOT NULL, "verificador_valido" bool NOT NULL, "resultado" integer NOT NULL, "estado_validacion" varchar(20) NOT NULL, "observacion" text NULL, "fecha_carga" datetime NOT NULL, "id_funcionario" integer NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "imagen" varchar(100) NULL, "fecha_evidencia" date NULL, "id_gestion_social_id" integer NULL REFERENCES "gestiones_sociales" ("id_gestion_social") DEFERRABLE INITIALLY DEFERRED, "tipo_archivo" varchar(60) NOT NULL, "verificador_id" integer NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "id_actividad" integer NULL REFERENCES "actividades" ("id_actividad") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "funcionarios" ("id_funcionario" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(200) NOT NULL, "cargo" varchar(150) NOT NULL, "activo" bool NOT NULL, "fecha_ingreso" date NULL, "id_delegacion" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "apellidos" varchar(120) NOT NULL, "correo" varchar(254) NULL, "estado" varchar(20) NOT NULL, "nombres" varchar(120) NOT NULL, "rut" varchar(20) NULL, "telefono" varchar(30) NULL, "cargo_rel_id" integer NULL REFERENCES "cargos_funcionarios" ("id_cargo") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gestiones_sociales" ("id_gestion_social" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codigo" varchar(30) NULL UNIQUE, "fecha_ingreso" date NOT NULL, "usuario" varchar(200) NOT NULL, "rut" varchar(20) NULL, "telefono" varchar(30) NULL, "direccion" varchar(250) NULL, "requiere_visita" bool NOT NULL, "fecha_programada_visita" date NULL, "ingreso_tubo" bool NOT NULL, "observaciones" text NOT NULL, "primera_gestion" varchar(200) NOT NULL, "segunda_gestion" varchar(200) NULL, "fecha_visita" date NULL, "fecha_entrega_informe" date NULL, "tercera_gestion" varchar(200) NULL, "fecha_entrega_beneficio" date NULL, "estado" varchar(30) NOT NULL, "imagen_verificada" bool NOT NULL, "verificador_valido" integer NOT NULL, "resultado" integer NOT NULL, "fecha_registro" datetime NOT NULL, "id_delegacion" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "id_funcionario" integer NOT NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "id_subatencion" integer NOT NULL REFERENCES "sub_atenciones" ("id_subatencion") DEFERRABLE INITIALLY DEFERRED, "id_tipo" integer NOT NULL REFERENCES "tipos_atencion" ("id_tipo") DEFERRABLE INITIALLY DEFERRED, "asignacion_meta_id" integer NULL REFERENCES "metas_funcionario" ("id_meta") DEFERRABLE INITIALLY DEFERRED, "beneficiario_vecino_id" integer NULL REFERENCES "vecinos" ("id_vecino") DEFERRABLE INITIALLY DEFERRED, "beneficio_entregado" varchar(200) NOT NULL, "derivacion" varchar(200) NOT NULL, "fecha_atencion" date NULL, "informe_detalle" text NOT NULL, "resultado_texto" varchar(255) NOT NULL);
CREATE TABLE "hitos_territoriales" ("id_hito" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codigo" varchar(20) NULL UNIQUE, "nombre" varchar(200) NOT NULL, "descripcion" text NOT NULL, "periodicidad" varchar(30) NOT NULL, "fecha_inicio" date NOT NULL, "fecha_termino" date NOT NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL, "delegacion_id" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "responsable_id" integer NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "territorio_id" integer NULL REFERENCES "territorios" ("id_territorio") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "hitos_territoriales_responsables" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "hito_id" integer NOT NULL REFERENCES "hitos_territoriales" ("id_hito") DEFERRABLE INITIALLY DEFERRED, "funcionario_id" integer NOT NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "indicadores_delegacion" ("id_indicador" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "area" varchar(150) NOT NULL, "responsable" varchar(200) NOT NULL, "avance_porcentaje" decimal NOT NULL, "estado_semaforo" varchar(10) NOT NULL, "licencias" integer NOT NULL, "vacaciones" integer NOT NULL, "emergencias" integer NOT NULL, "compensatorios" integer NOT NULL, "id_delegacion" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "id_periodo" integer NULL REFERENCES "periodos_evaluacion" ("id_periodo") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "items_metas" ("id_item" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codigo" varchar(20) NULL UNIQUE, "nombre" varchar(200) NOT NULL UNIQUE, "descripcion" text NOT NULL, "tipo_meta" varchar(50) NOT NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL, "requisito_evidencia" varchar(200) NOT NULL, "unidad_medida" varchar(120) NOT NULL);
CREATE TABLE "juntas_vecinos" ("id_junta" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codigo" varchar(20) NULL UNIQUE, "nombre" varchar(250) NOT NULL UNIQUE, "direccion" varchar(250) NOT NULL, "fecha_constitucion" date NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL, "delegacion_id" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "territorio_id" integer NULL REFERENCES "territorios" ("id_territorio") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "metas_funcionario" ("id_meta" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "item" varchar(200) NOT NULL, "ponderador" decimal NOT NULL, "meta_periodo" integer NOT NULL, "avance_actual" integer NOT NULL, "porcentaje_cumplimiento" decimal NOT NULL, "cumplimiento_ponderado" decimal NOT NULL, "felicitaciones" integer NOT NULL, "reclamos" integer NOT NULL, "id_funcionario" integer NOT NULL REFERENCES "funcionarios" ("id_funcionario") DEFERRABLE INITIALLY DEFERRED, "id_periodo" integer NULL REFERENCES "periodos_evaluacion" ("id_periodo") DEFERRABLE INITIALLY DEFERRED, "codigo" varchar(30) NULL UNIQUE, "estado" varchar(20) NOT NULL, "fecha_asignacion" date NULL, "id_item_meta_id" integer NULL REFERENCES "items_metas" ("id_item") DEFERRABLE INITIALLY DEFERRED, "observacion" text NOT NULL);
CREATE TABLE "participaciones_juntas" ("id_participacion" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "es_dirigente" bool NOT NULL, "cargo" varchar(100) NOT NULL, "fecha_incorporacion" date NULL, "estado" varchar(20) NOT NULL, "fecha_registro" datetime NOT NULL, "junta_id" integer NOT NULL REFERENCES "juntas_vecinos" ("id_junta") DEFERRABLE INITIALLY DEFERRED, "vecino_id" integer NOT NULL REFERENCES "vecinos" ("id_vecino") DEFERRABLE INITIALLY DEFERRED, "codigo" varchar(20) NULL UNIQUE);
CREATE TABLE "perfiles_usuarios" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "telefono" varchar(30) NULL, "estado" varchar(20) NOT NULL, "codigo_recuperacion" varchar(6) NULL, "codigo_expiracion" datetime NULL, "intentos_fallidos" integer NOT NULL, "codigo_usado" bool NOT NULL, "ultimo_reenvio" datetime NULL, "delegacion_activa_id" integer NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "rol_id" integer NULL REFERENCES "roles" ("id_rol") DEFERRABLE INITIALLY DEFERRED, "rut" varchar(20) NULL, "cargo_id" integer NULL REFERENCES "cargos_funcionarios" ("id_cargo") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "perfiles_usuarios_delegaciones_autorizadas" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "perfilusuario_id" bigint NOT NULL REFERENCES "perfiles_usuarios" ("id") DEFERRABLE INITIALLY DEFERRED, "delegacion_id" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "perfiles_usuarios_roles" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "perfilusuario_id" bigint NOT NULL REFERENCES "perfiles_usuarios" ("id") DEFERRABLE INITIALLY DEFERRED, "rol_id" integer NOT NULL REFERENCES "roles" ("id_rol") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "periodos_evaluacion" ("id_periodo" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL, "fecha_inicio" date NOT NULL, "fecha_cierre" date NOT NULL, "dias_totales" integer NOT NULL, "dias_transcurridos" integer NOT NULL, "activo" bool NOT NULL, "anio" integer NOT NULL, "codigo" varchar(20) NULL UNIQUE, "estado" varchar(20) NOT NULL, "numero" integer NOT NULL);
CREATE TABLE "roles" ("id_rol" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(100) NOT NULL UNIQUE, "descripcion" text NOT NULL, "alcance_autorizado" varchar(30) NOT NULL, "permisos" varchar(255) NOT NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL, "grupo_django_id" integer NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "codigo" varchar(20) NULL UNIQUE);
CREATE TABLE "sub_atenciones" ("id_subatencion" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(150) NOT NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL, "id_tipo" integer NOT NULL REFERENCES "tipos_atencion" ("id_tipo") DEFERRABLE INITIALLY DEFERRED, "codigo" varchar(20) NULL UNIQUE);
CREATE TABLE "territorios" ("id_territorio" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "codigo" varchar(20) NULL UNIQUE, "nombre" varchar(200) NOT NULL, "descripcion" text NOT NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL, "delegacion_id" integer NOT NULL REFERENCES "delegaciones" ("id_delegacion") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tipos_atencion" ("id_tipo" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(150) NOT NULL UNIQUE, "descripcion" text NOT NULL, "estado" varchar(20) NOT NULL, "fecha_creacion" datetime NOT NULL, "codigo" varchar(20) NULL UNIQUE);
CREATE TABLE "vecinos" ("id_vecino" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rut" varchar(20) NOT NULL UNIQUE, "nombre" varchar(200) NOT NULL, "telefono" varchar(30) NULL, "correo" varchar(254) NULL, "direccion" varchar(250) NULL, "territorio" varchar(200) NULL, "fecha_registro" datetime NOT NULL, "apellidos" varchar(120) NOT NULL, "estado" varchar(20) NOT NULL, "nombres" varchar(120) NOT NULL, "territorio_rel_id" integer NULL REFERENCES "territorios" ("id_territorio") DEFERRABLE INITIALLY DEFERRED);
